export type ReferencesIncomplete = 
/**  A language server was still indexing. */
"indexing" | 
/**  More project files mention the name than were checked. */
"tooManyFiles" | 
/**  Files that mention the name were too large or unreadable to check. */
"filesSkipped" | 
/**  A native query failed; indexed anchors are still available. */
"serverFailed";

export type RegisteredRunTarget = {
	/**  Opaque selector id, namespaced by the host. */
	id: string,
	pluginId: string,
	pluginName: string,
	target: PluginRunTarget,
	prompt: boolean,
};

/**  A registry agent this machine can run (or has installed). */
export type RegistryAgent = {
	id: string,
	name: string,
	/**  The registry's current version. */
	version: string,
	description: string,
	repository: string | null,
	website: string | null,
	authors: string[],
	license: string | null,
	/**
	 *  How it installs here; `None` when it no longer can (an installed agent whose
	 *  runtime went away).
	 */
	distribution: RegistryDistribution | null,
	/**
	 *  The release archive comes without a SHA-256, so the download cannot be checked.
	 *  npm and uv packages are checked by those tools.
	 */
	noChecksum: boolean,
	/**  The installed version. */
	installed: string | null,
	/**  Whether [`Self::version`] is newer than the installed one. */
	update: boolean,
	/**  An install of it is running (it goes on after the Settings page that started it closes). */
	installing: boolean,
};

export type RegistryDistribution = 
/**  A release archive for this OS and architecture. */
"binary" | 
/**  An npm package (needs Node.js). */
"npx" | 
/**  A Python package run by uv. */
"uvx";

export type Remote = {
	name: string,
	/**  Fetch URL. */
	url: string,
	/**  Fetch URL with any `~/.ssh/config` host alias resolved, when different from `url`. */
	resolvedUrl?: string | null,
};

/**  Manage Remotes edits. */
export type RemoteEdit = { op: "add"; name: string; url: string } | { op: "remove"; name: string } | 
/**  Renames `name` to `new_name` (when different) and sets its URL. */
{ op: "edit"; name: string; new_name: string; url: string };

/**  A remote directory entry. */
export type RemoteEntry = {
	name: string,
	/**  Absolute remote path. */
	path: string,
	isDir: boolean,
	isSymlink: boolean,
	size: number,
	/**  Seconds since the Unix epoch. */
	mtime: number | null,
	/**  `rwxr-xr-x`. */
	permissions: string,
};

/**  A project folder on an SSH host, in a WSL distribution or in a dev container. */
export type RemoteLaunch = {
	target: RemoteTarget,
	path: string,
};

export type RemoteOp = { op: "fetch" } | { op: "pull"; rebase: boolean } | 
/**  Update Project › Reset to the Remote Branch. */
{ op: "resetToUpstream" } | { op: "push"; force_with_lease: boolean; set_upstream: boolean; 
/**  Push dialog › Push tags. */
tags?: PushTags | null; 
/**  Plain `--force` (Force push anyway). */
force?: boolean; 
/**  Push dialog › Run Git hooks unchecked (`--no-verify`). */
no_verify?: boolean } | 
/**  Deletes a remote branch; `branch` is the remote-tracking name (`origin/feature`). */
{ op: "deleteBranch"; branch: string } | 
/**
 *  Pushes local `branch` (only up to `revision` when set) to its upstream, or to
 *  remote branch `target`; `remote` overrides the upstream's remote (Push dialog's
 *  remote picker).
 */
{ op: "pushBranch"; branch: string; revision: string | null; force_with_lease: boolean; target?: string | null; remote?: string | null; force?: boolean; 
/**  Record the target as upstream (Push dialog › Set upstream). */
set_upstream?: boolean; no_verify?: boolean } | 
/**  Push Tag › Push to `remote`. */
{ op: "pushTag"; tag: string; remote: string } | 
/**  Deletes tag `tag` on `remote` (Delete on Remote). */
{ op: "deleteRemoteTag"; tag: string; remote: string } | 
/**  Pull dialog: `branches` of `remote` (none = the configured merge branch). */
{ op: "pullFrom"; remote: string; branches: string[]; rebase: boolean; options: MergeOptions };

export type RemoteProgress = {
	stage: RemoteStage,
	fraction: number | null,
};

export type RemoteProject = RemoteProject_Serialize | RemoteProject_Deserialize;

export type RemoteProject_Deserialize = {
	target: RemoteTarget,
	root: string,
	/**  `user@host:port` of the SSH configuration; the distribution name for WSL. */
	host: string,
	serverVersion: string,
	os: string,
	/**  Commands routed to the server (the rest run locally). */
	commands: string[],
	project: ProjectInfo_Deserialize,
};

export type RemoteProject_Serialize = {
	target: RemoteTarget,
	root: string,
	/**  `user@host:port` of the SSH configuration; the distribution name for WSL. */
	host: string,
	serverVersion: string,
	os: string,
	/**  Commands routed to the server (the rest run locally). */
	commands: string[],
	project: ProjectInfo_Serialize,
};

export type RemoteSession = {
	target: RemoteTarget,
	root: string,
	host: string,
	/**  `linux`, `macos` or `windows`: the OS the project's commands run on. */
	os: string,
	commands: string[],
};

/**  Where [`remote_connect`] is (`fraction`: 0..1 of a download / upload). */
export type RemoteStage = "connecting" | 
/**  `devcontainer up`: building or starting the container. */
"container" | "checking" | "downloading" | "uploading" | "starting" | "opening";

/**  Where a remote project lives and how the server there is reached. */
export type RemoteTarget = 
/**  The host of SSH configuration `config`. */
{ kind: "ssh"; config: string } | 
/**  A WSL distribution on this machine. */
{ kind: "wsl"; distro: string } | 
/**
 *  The dev container of local folder `folder`, built and started with the Dev Containers CLI;
 *  `config` is its `devcontainer.json`, relative to the folder (empty = the default one).
 */
{ kind: "devContainer"; folder: string; config: string };

export type Renamed = {
	/**  Indexed names always require preview, including a single-file rename. */
	preview?: boolean,
	edit: WorkspaceEdit,
	incomplete: ReferencesIncomplete | null,
};

export type ReplaceEvent = 
/**  A file was changed (`replacements` > 0) or had nothing left to replace. */
{ type: "file"; path: IpcPath; replacements: number; done: number; total: number } | { type: "failed"; path: IpcPath; message: string; done: number; total: number } | { type: "done"; summary: ReplaceSummary };

/**  Before / after text of one file for the Replace preview. */
export type ReplacePreview = {
	before: string,
	after: string,
	edits: TextEdit[],
};

export type ReplaceSummary = {
	/**  Files actually changed. */
	files: number,
	replacements: number,
	failed: number,
	cancelled: boolean,
	elapsedMs: number,
};

/**  One file to replace in. */
export type ReplaceTarget = {
	path: IpcPath,
	/**
	 *  Start positions (0-based line, UTF-16 column) of the matches to replace,
	 *  as reported by the search; `None` replaces every match in the file.
	 *  Positions where no match starts any more are skipped.
	 */
	only?: Pos[] | null,
	/**
	 *  Start positions of matches to leave as they are (excluded or already
	 *  replaced usages) when every other match in the file is replaced.
	 */
	skip?: Pos[] | null,
};

export type RepositoryComparison = {
	root: IpcPath,
	/**  Resolved commit, so opening a diff later uses the same left side as the listing. */
	revision: string | null,
	files: WorkingTreeChange[],
	error: string | null,
	/**  The requested revision does not resolve to a commit in this repository. */
	missingRevision?: boolean,
};

/**  A cancellable, streaming backend request issued by the UI. */
export type RequestId = number;

/**  A program a generator needs, and whether this machine has it. */
export type Requirement = {
	program: string,
	min: string | null,
	/**  The version found; `None` when the program is missing or reports none. */
	found: string | null,
	satisfied: boolean,
	hint: string,
};

/**  `git reset` modes offered by Reset Current Branch to Here. */
export type ResetMode = "soft" | "mixed" | "hard" | "keep";

/**  A mapping resolved by the backend for the Remote Host browser. */
export type ResolvedMapping = {
	local: IpcPath,
	deployment: string,
};

export type ReviewEvent = "approve" | "requestChanges" | "comment";

/**  A file changed across several commits: its content at `before` ↔ at `after`. */
export type RevisionChange = {
	/**  Repository-relative path after the change (before it, for a deletion). */
	path: string,
	kind: ChangeKind,
	/**  Path at `before`, for a rename. */
	oldPath: string | null,
	/**  Commit holding the old content; `None` when the file was added. */
	before: string | null,
	/**  Commit holding the new content; `None` when the file was deleted. */
	after: string | null,
	/**  Set when the entry is a symbolic link, resolved at `after` (`before`, for a deletion). */
	link?: LinkTarget | null,
};

/**  How a grant is presented (plan 4.2). */
export type Risk = 
/**  Listed on the install page, one confirmation. */
"low" | 
/**  Listed separately with its purpose. */
"medium" | 
/**  Separate dialog: "equivalent to running arbitrary code on this machine". */
"high";

export type RootKind = "source" | "test" | "resources" | "testResources" | "excluded";

export type RouteSource = {
	path: IpcPath,
	text: string,
};

export type RubySettings = {
	/**  Project interpreter executable; empty = auto-detect (`.ruby-version`, mise / asdf, else `ruby` on PATH). */
	interpreter?: string,
};

export type RunConfig = RunConfig_Serialize | RunConfig_Deserialize;

export type RunConfig_Deserialize = {
	/**  Stable id, e.g. `npm:dev`, `cargo:run:app`, or a uuid for user-defined. */
	id: string,
	name: string,
	/**  `npm` | `cargo` | `gradle` | `maven` | `go` | `python` | `pytest` | `make` | `shell` … */
	kind: string,
	command: string,
	args: string[],
	cwd: IpcPath | null,
	env: { [key in string]: string },
	/**  Detected configs are regenerated; user configs persist in `.openidea/run.toml`. */
	detected: boolean,
	/**  Test runner configs render results in the test tree. */
	isTest: boolean,
	/**  DAP adapter that can debug this config, if any. */
	debugAdapter: string | null,
	/**  "Allow multiple instances": Run on a running config starts another one instead of restarting it. */
	allowParallel?: boolean,
} & RunExtras_Deserialize;

export type RunConfig_Serialize = {
	/**  Stable id, e.g. `npm:dev`, `cargo:run:app`, or a uuid for user-defined. */
	id: string,
	name: string,
	/**  `npm` | `cargo` | `gradle` | `maven` | `go` | `python` | `pytest` | `make` | `shell` … */
	kind: string,
	command: string,
	args: string[],
	cwd: IpcPath | null,
	env: { [key in string]: string },
	/**  Detected configs are regenerated; user configs persist in `.openidea/run.toml`. */
	detected: boolean,
	/**  Test runner configs render results in the test tree. */
	isTest: boolean,
	/**  DAP adapter that can debug this config, if any. */
	debugAdapter: string | null,
	/**  "Allow multiple instances": Run on a running config starts another one instead of restarting it. */
	allowParallel?: boolean,
} & RunExtras_Serialize;

/**  RunExited data exchanged with the IDE. */
export type RunExited = {
	id: string,
	config: string,
	status: number | null,
	killed: boolean,
};

export type RunExtras = RunExtras_Serialize | RunExtras_Deserialize;

export type RunExtras_Deserialize = {
	/**
	 *  Owning module, independent of the working directory; also supplies a JVM application's classpath.
	 *  Empty means the project root.
	 */
	module?: string | null,
	/**  Values of the configuration type's own form fields (the command line derives from them). */
	params?: { [key in string]: string },
	/**  Folder in the Run/Debug Configurations tree. */
	folder?: string | null,
	/**  Stored in the workspace (`.openidea/run.local.toml`, not shared) instead of `run.toml`. */
	local?: boolean,
	/**  Off: the process gets only the configured variables. */
	includeSystemEnv?: boolean,
	/**  `.env` files (relative to the project root) loaded before `env`, in order. */
	envFiles?: string[],
	/**  "Redirect input from": the process reads this file as stdin. */
	stdinFile?: string | null,
	/**  "Save console output to file" (overwritten on each run). */
	outputFile?: string | null,
	beforeLaunch?: BeforeLaunchTask[],
	/**  Before launch build for JVM launches; unset keeps the project's default (incremental). */
	buildPolicy?: BuildPolicy | null,
	/**  Compound configurations: ids of the configurations started together. */
	compound?: string[],
	showOnStdout?: boolean,
	showOnStderr?: boolean,
	/**  Overrides Settings › Run › "Show the Run tool window when a process starts". */
	openToolWindow?: boolean | null,
	focusToolWindow?: boolean,
	/**
	 *  "Emulate terminal in output console": the process runs on a pseudo-terminal
	 *  (colours, line editing, full-screen programs); the console renders it as a terminal.
	 */
	emulateTerminal?: boolean,
	/**
	 *  Shell command line run on Stop before the process is signalled (e.g. `docker stop <name>`),
	 *  with the run's working directory and environment.
	 */
	stopCommand?: string | null,
	/**  Settings › Run Targets id the process runs on (over SSH); `None` = this machine. */
	target?: string | null,
};

export type RunExtras_Serialize = {
	/**
	 *  Owning module, independent of the working directory; also supplies a JVM application's classpath.
	 *  Empty means the project root.
	 */
	module?: string | null,
	/**  Values of the configuration type's own form fields (the command line derives from them). */
	params?: { [key in string]: string },
	/**  Folder in the Run/Debug Configurations tree. */
	folder?: string | null,
	/**  Stored in the workspace (`.openidea/run.local.toml`, not shared) instead of `run.toml`. */
	local?: boolean,
	/**  Off: the process gets only the configured variables. */
	includeSystemEnv?: boolean,
	/**  `.env` files (relative to the project root) loaded before `env`, in order. */
	envFiles?: string[],
	/**  "Redirect input from": the process reads this file as stdin. */
	stdinFile?: string | null,
	/**  "Save console output to file" (overwritten on each run). */
	outputFile?: string | null,
	beforeLaunch?: BeforeLaunchTask[],
	/**  Before launch build for JVM launches; unset keeps the project's default (incremental). */
	buildPolicy?: BuildPolicy | null,
	/**  Compound configurations: ids of the configurations started together. */
	compound?: string[],
	showOnStdout?: boolean,
	showOnStderr?: boolean,
	/**  Overrides Settings › Run › "Show the Run tool window when a process starts". */
	openToolWindow?: boolean | null,
	focusToolWindow?: boolean,
	/**
	 *  "Emulate terminal in output console": the process runs on a pseudo-terminal
	 *  (colours, line editing, full-screen programs); the console renders it as a terminal.
	 */
	emulateTerminal?: boolean,
	/**
	 *  Shell command line run on Stop before the process is signalled (e.g. `docker stop <name>`),
	 *  with the run's working directory and environment.
	 */
	stopCommand?: string | null,
	/**  Settings › Run Targets id the process runs on (over SSH); `None` = this machine. */
	target?: string | null,
};

/**  A process started from a run configuration. */
export type RunId = number;

/**  What an import found: configurations to add and entries left out, with the reason. */
export type RunImport = RunImport_Serialize | RunImport_Deserialize;

/**  Project files run configurations can be imported from. */
export type RunImportSource = 
/**  VS Code's `.vscode/launch.json`. */
"vscode" | 
/**  JetBrains IDEs' `.run/*.run.xml`, `.idea/runConfigurations/*.xml` and `.idea/workspace.xml`. */
"jetbrains";

/**  What an import found: configurations to add and entries left out, with the reason. */
export type RunImport_Deserialize = {
	source: RunImportSource,
	/**  The file read, relative to the project root. */
	file: string,
	imported: ImportedRunConfig_Deserialize[],
	skipped: SkippedRunConfig[],
};

/**  What an import found: configurations to add and entries left out, with the reason. */
export type RunImport_Serialize = {
	source: RunImportSource,
	/**  The file read, relative to the project root. */
	file: string,
	imported: ImportedRunConfig_Serialize[],
	skipped: SkippedRunConfig[],
};

export type RunInfo = {
	id: RunId,
	configId: string,
	name: string,
	pid: number | null,
	running: boolean,
	/**  Runs on a pseudo-terminal: output is raw terminal data, input goes in keystroke by keystroke. */
	pty: boolean,
};

/**  Run/Debug configuration behaviour. */
export type RunSettings = {
	/**  Target for configurations without an explicit target. Empty = local. */
	defaultTarget?: string,
	confirmRerun?: boolean,
	/**  Ask before closing a Run tab whose process is still running. */
	confirmTerminate?: boolean,
	showOnStart?: boolean,
	/**  New Run/Debug tabs start pinned: a later run doesn't take their place once finished. */
	pinTabs?: boolean,
	/**  Grace period between interrupt and kill when stopping a process. */
	terminationTimeoutMs?: number,
};

/**
 *  Build, Execution, Deployment › Run Targets: run configurations on another machine
 *  or in a container.
 */
export type RunTarget = {
	kind?: RunTargetKind,
	id?: string,
	name?: string,
	/**  [`SshConfiguration::id`] (SSH). */
	sshConfig?: string,
	/**  Remote folder the project is synchronised to and run from (SSH). */
	projectRoot?: string,
	/**  Upload changed project files before each run (SSH). */
	syncBeforeRun?: boolean,
	/**  Interpreters on the target; empty = the one on the remote `PATH`. */
	python?: string,
	node?: string,
	java?: string,
	/**
	 *  Id of a Docker connection of the Services tool window (Docker, Compose);
	 *  empty = the CLI's own daemon.
	 */
	dockerConnection?: string,
	/**  Image to run (Docker). */
	image?: string,
	/**  Compose files, relative to the project; empty = the project's default one (Compose). */
	composeFiles?: string[],
	/**  Service to run (Compose). */
	service?: string,
	/**
	 *  Where the project is in the container; empty = `/workspaces/<folder>` (Docker),
	 *  the service's bind mount of the project (Compose).
	 */
	containerRoot?: string,
	/**  Published ports, as `docker run --publish` takes them (`8000:8000`). */
	ports?: string[],
	/**  More options for `docker run` / `docker compose run`, shell-like quoted. */
	runOptions?: string,
	/**  Run as the image's user instead of the project folder's owner (Linux). */
	imageUser?: boolean,
};

/**  Where a run target runs configurations. */
export type RunTargetKind = 
/**  Another machine over SSH, the project synchronised to its folder. */
"ssh" | 
/**  A new container of an image (`docker run --rm`), the project bind-mounted. */
"docker" | 
/**  A new container of a Compose service (`docker compose run --rm`). */
"compose";

export type RustSettings = {
	/**  Directory holding `cargo` / `rustc`; empty = `PATH` / rustup default. */
	toolchain?: string,
	/**  Standard library sources (`RUST_SRC_PATH`); empty = from the toolchain. */
	stdlib?: string,
	/**  Run the external linter on save (rust-analyzer `checkOnSave`). */
	checkOnSave?: boolean,
	/**  `check` | `clippy` (rust-analyzer `check.command`). */
	checkCommand?: string,
	/**  Extra arguments for rustfmt (rust-analyzer `rustfmt.extraArgs`), space-separated. */
	rustfmtArgs?: string,
};

export type SbtBuild = {
	/**  Folder of `build.sbt`, relative to the project root (`""` for the root itself). */
	dir: string,
	/**  The launcher: a `sbt` / `sbtx` script in the build folder, else `sbt` on `PATH`. */
	command: string,
	/**  `sbt.version` of `project/build.properties`. */
	version: string | null,
	/**  The root project first, then the declared projects in source order. */
	projects: SbtProject[],
};

export type SbtProject = {
	/**  The project id tasks are scoped with (`core/compile`). */
	id: string,
	/**  Base folder relative to the build folder (`""` for the build's own). */
	dir: string,
	/**  The build's root project: its tasks run unscoped (and aggregate when sbt does). */
	root: boolean,
};

/**  Progress of `scaffold_create`. */
export type ScaffoldEvent = 
/**  A new step began. */
{ type: "step"; text: string } | 
/**  A line of a tool's output. */
{ type: "line"; text: string };

export type Scope = {
	name: string,
	variablesReference: number,
	expensive: boolean,
};

/**  The files of a custom scope (`file:src//*.ts`), for the Project view's scope panes. */
export type ScopeFiles = {
	paths: IpcPath[],
	/**  More files than `limit` matched; `paths` holds the first ones. */
	truncated: boolean,
};

/**  One installed interpreter / toolchain. */
export type Sdk = {
	/**
	 *  Executable (`python`, `node`, `pnpm`) or directory (Rust toolchain bin
	 *  dir, GOROOT, TypeScript `lib` dir) that the setting stores.
	 */
	path: IpcPath,
	/**  Display name, e.g. `Python 3.12 (.venv)` or `stable-aarch64-apple-darwin`. */
	name: string,
	version: string | null,
	/**
	 *  Where it was found: `venv` | `system` | `pyenv` | `conda` | `uv` | `nvm` |
	 *  `rustup` | `bundled` | `workspace` | `path` …
	 */
	source: string,
	/**  Environment / toolchain root (virtualenv dir, rustup toolchain dir, GOROOT). */
	home: IpcPath | null,
	/**  Rust standard library sources, Go default GOPATH. */
	extra: IpcPath | null,
};

/**  What [`detect`] looks for. */
export type SdkKind = "python" | "node" | 
/**  `php` CLI executables. */
"php" | 
/**  npm / pnpm / yarn executables. */
"packageManager" | "rust" | "go" | "typeScript" | 
/**  JDK homes. */
"jdk" | 
/**  Maven homes. */
"maven" | "ruby" | 
/**  Zig toolchain directories. */
"zig";

/**
 *  IDEA's search context: matches anywhere, only in, or outside comments and
 *  string literals. Files whose language has no syntax tree contain neither.
 */
export type SearchContext = "any" | "inComments" | "inStringLiterals" | "exceptComments" | "exceptStringLiterals" | "exceptCommentsAndStringLiterals";

export type SearchEvent = { type: "file"; file: FileMatches } | { type: "done"; summary: SearchSummary };

export type SearchQuery = {
	pattern: string,
	isRegex: boolean,
	caseSensitive: boolean,
	wholeWord: boolean,
	/**
	 *  File masks, e.g. `*.kt`, `src/**\/*.ts`; an entry may also be a
	 *  comma-separated list where `!mask` excludes. Empty = all files.
	 */
	include: string[],
	exclude: string[],
	scope: SearchScope,
	/**  Stop after this many matches overall (0 = 10 000). */
	maxMatches: number,
	/**  Where in the code a match may lie (IDEA's search context filter). */
	context?: SearchContext,
	/**
	 *  Also search what `.gitignore` / `.ignore` / `info/exclude` leave out (the caller then
	 *  adds none of the project's exclusions either).
	 */
	includeExcluded?: boolean,
};

export type SearchScope = { kind: "project" } | { kind: "directory"; path: IpcPath } | { kind: "files"; paths: IpcPath[] } | 
/**
 *  IDEA's named scopes over the project's roots ("Project Production Files" …).
 *  Walks the project like `Project`; the caller passes the matching [`PathFilter`].
 */
{ kind: "fileSet"; set: ProjectFileSet } | 
/**
 *  A custom scope: the project's files matching a [`ScopePattern`]
 *  (`file:src//*.ts&&!file:*test*`).
 */
{ kind: "pattern"; pattern: string };

export type SearchSummary = {
	files: number,
	matches: number,
	limitHit: boolean,
	cancelled: boolean,
	elapsedMs: number,
};

/**  Decoded semantic tokens (absolute positions) with the server legend applied. */
export type SemanticTokens = {
	/**  Flattened `[line, col, len, typeIdx, modifierBits]` quintuples (absolute). */
	data: number[],
	tokenTypes: string[],
	tokenModifiers: string[],
};

/**  The key that sends a message; the other one starts a new line. */
export type SendKey = "enter" | "modEnter";

/**  A running language server instance. */
export type ServerId = number;

export type ServerInfo = {
	id: ServerId,
	name: string,
	root: IpcPath,
	languages: LanguageId[],
	status: ServerStatus,
	/**  OS process of the running instance (for memory attribution). */
	pid: number | null,
	/**  What the user sees as the server when another program serves in its place. */
	label?: string | null,
};

/**
 *  A refactoring checked by the server (Change Signature, Move, Extract Interface): problems to show, the edit when
 *  none is fatal, and the token that confirms going on despite warnings.
 */
export type ServerRefactored = {
	problems: RefactoringProblem[],
	edit: WorkspaceEdit | null,
	confirmation: string | null,
};

export type ServerStatus = "starting" | "ready" | "busy" | "crashed" | "stopped" | "missing" | 
/**
 *  Not started: its configuration can't launch it (e.g. no JDK new enough);
 *  the message says what to change, and a settings change retries.
 */
"misconfigured";

export type ServiceLog = {
	program: string,
	args: string[],
	toggles: ServiceLogToggle[],
};

/**  A switch above the log; when on, `args` are appended and the program restarts. */
