/**  Highlight classes sent to the UI, which maps each onto a Lezer tag. */
export type SyntaxHighlightKind = "keyword" | "string" | "stringSpecial" | "escape" | "regexp" | "atom" | "number" | "constant" | "comment" | "docComment" | "function" | "functionCall" | "builtin" | "type" | "namespace" | "variable" | "selfVariable" | "property" | "attribute" | "macro" | "label" | "tag" | "operator" | "punctuation" | "parameter" | 
/**  A shell command name (`pgrep`, a script's own function). */
"command";

/**  Highlighted ranges of a whole document, packed like LSP semantic tokens. */
export type SyntaxHighlights = {
	/**  Legend: `data` kind `i` is `kinds[i]`. */
	kinds: SyntaxHighlightKind[],
	/**  `[from, to, kind]` triples: sorted, non-overlapping UTF-16 offsets. */
	data: number[],
};

/**  One tree-sitter node. */
export type SyntaxNode = {
	/**  Grammar node kind, e.g. `method_invocation`, `identifier`, `;`. */
	kind: string,
	range: Range,
	/**  Field name of this node in its parent (`name`, `body`, `condition`…). */
	field: string | null,
	/**  Named node (anonymous tokens such as `;` or `(` are not named). */
	named: boolean,
	/**  The node is an `ERROR` node. */
	error: boolean,
	/**  The parser inserted the node to recover (e.g. a missing `;`); its range is empty. */
	missing: boolean,
	/**  The node or a descendant is an error / missing node. */
	hasError: boolean,
};

